#include <iostream>
#include <algorithm>
#include <string>

using namespace std;

using i128 = __int128_t;

i128 floor_div(i128 n, i128 d) {
    i128 q = n / d;
    i128 r = n % d;
    if (r < 0) --q;
    return q;
}

void print_i128(i128 value) {
    if (value == 0) {
        cout << 0;
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string s;
    while (value > 0) {
        s.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b, x, y, x2, y2;
    cin >> a >> b >> x >> y >> x2 >> y2;

    i128 k1 = floor_div((i128)y - x, (i128)2 * b) + 1;
    i128 k2 = floor_div((i128)y2 - x2, (i128)2 * b) + 1;
    i128 res1 = k1 > k2 ? k1 - k2 : k2 - k1;

    k1 = floor_div((i128)x + y, (i128)2 * a) + 1;
    k2 = floor_div((i128)x2 + y2, (i128)2 * a) + 1;
    i128 res2 = k1 > k2 ? k1 - k2 : k2 - k1;

    print_i128(max(res1, res2));
    return 0;
}

