#include <iostream>
#include <algorithm>
#include <cstdlib>
using namespace std;

long long floor_div(long long value, long long divisor) {
    long long quotient = value / divisor;
    long long remainder = value % divisor;
    if (remainder != 0 && ((remainder < 0) != (divisor < 0)))
        --quotient;
    return quotient;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b, x, y, x2, y2;
    cin >> a >> b >> x >> y >> x2 >> y2;

    long long k1 = floor_div(y - x, 2 * b) + 1;
    long long k2 = floor_div(y2 - x2, 2 * b) + 1;
    long long res1 = llabs(k2 - k1);

    k1 = floor_div(x + y, 2 * a) + 1;
    k2 = floor_div(x2 + y2, 2 * a) + 1;
    long long res2 = llabs(k2 - k1);

    cout << max(res1, res2);
    return 0;
}

